import manifest from '@/generated/image-manifest.json';

export interface ImageVariant { src: string; width: number }
export interface ImageEntry {
  width: number;
  height: number;
  variants: ImageVariant[];
}

const entries = manifest as Record<string, ImageEntry>;

/** The manifest is generated by Sharp at build/dev startup. */
export function imageEntry(src: string): ImageEntry | undefined {
  return entries[src];
}

export function responsiveImage(src: string): {
  srcSet?: string;
  width?: number;
  height?: number;
} {
  const entry = imageEntry(src);
  if (!entry) return {};
  return {
    srcSet: entry.variants.map(variant => `${variant.src} ${variant.width}w`).join(', '),
    width: entry.width,
    height: entry.height,
  };
}
